<?php

namespace App\Console\Commands;

use App\Enums\HexCodes;
use Exception;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\Log;

class StartMindrayClientCommand extends Command
{

    public const VT = HexCodes::VT->value;
    public const FS = HexCodes::FS->value;
    public const CR = HexCodes::CR->value;

    private $socket;
    private $connection;


    public function __construct()
    {
        parent::__construct();
        $this->socket = socket_create(AF_INET, SOCK_STREAM, SOL_TCP);
        if ($this->socket === false) {
            echo "Socket creation failed: " . socket_strerror(socket_last_error()) . "\n";
        }
    }

    /**
     * The name and signature of the console command.
     *
     * @var string
     */
    protected $signature = 'mindray:connect';

    /**
     * The console command description.
     *
     * @var string
     */
    protected $description = 'Mindray client sends messages to ths Mindray server';

    protected string $message = '';

    /**
     * Execute the console command.
     */
    public function handle(): void
    {
        $connection = $this->connect();
        if (!$connection) {
            echo "Error connecting to the server\n";
            return;
        }

        $this->process();
    }

    public function connect(): bool
    {
//        $ip = '85.206.48.46'; // rezus public address
//        $ip = '192.168.1.111'; // rezus local address
//        $port = 9999;

        $ip = '192.168.0.111';
        $port = 12000;

        // Attempt to connect to the socket server
        $this->connection = @socket_connect($this->socket, $ip, $port);

        if ($this->connection === false) {
            $errorMessage = socket_strerror(socket_last_error($this->socket));
            echo "Socket connection failed: $errorMessage\n";
            return false;
        }

        echo "Connection established\n";
        return true;
    }

    /**
     * @throws Exception
     */
    public function process(): void
    {
        $this->sendMessage($this->message);
        $response = socket_read($this->socket, 2048);
    }

    /**
     * @throws Exception
     */
    public function sendMessage($hexString): void
    {
        // Convert hexadecimal string to binary
        $binaryString = hex2bin($hexString);

        if ($binaryString === false) {
            throw new Exception("Hex to binary conversion failed");
        }

        // Ensure <CR> is correctly represented
        $binaryString = str_replace("\x0D", "\r", $binaryString);
        echo "Sending message: $binaryString\n";

        // Send the binary string via socket connection
        $result = socket_write($this->socket, $binaryString, strlen($binaryString));

        if ($result === false) {
            echo "Socket write failed: " . socket_strerror(socket_last_error($this->socket)) . "\n";
        } else {
            echo "Message sent successfully\n";
        }
    }

}
